/* ---------- インストール：本体と問題データを先に取り込む ---------- */
self.addEventListener('install', e => {
  e.waitUntil((async () => {
    const c = await caches.open(SHELL);
    // 本体・データが全て揃った世代だけを有効にする。
    await Promise.all(PRECACHE.map(u => c.add(new Request(u, { cache: 'reload' }))));
    self.skipWaiting();
  })());
});

// 大量の画像はアプリ本体の更新を妨げない別イベントで保存する。
let imageCaching = null;
function cacheTextbookImages() {
  if (imageCaching) return imageCaching;
  imageCaching = (async () => {
    // Book images are separate from startup JSON. Reuse content-addressed
    // images on updates, and limit background requests to four at a time.
    const images = await caches.open(FIGS);
    let nextImage = 0;
    await Promise.all(Array.from({length:4},async()=>{
      while(nextImage<TEXTBOOK_IMAGES.length){
        const url=TEXTBOOK_IMAGES[nextImage++];
        try{if(!await images.match(url)){const r=await fetch(url);if(r.ok)await images.put(url,r);}}
        catch(err){console.warn('[sw] textbook image skipped:',url);}
      }
    }));
  })().finally(() => { imageCaching = null; });
  return imageCaching;
}

/* ---------- 有効化：古いバージョンのキャッシュを掃除 ---------- */
self.addEventListener('activate', e => {
  e.waitUntil((async () => {
    const keys = await caches.keys();
    await Promise.all(keys.map(k => (k !== SHELL && k !== FIGS) ? caches.delete(k) : null));
    await self.clients.claim();
  })());
});

const isFig = url => /\/figs\//.test(url.pathname);

/* ---------- 取得 ---------- */
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;

  const url = new URL(req.url);
  // アプリ以外のURLは通常のネットワーク処理に任せる
  if (url.origin !== self.location.origin) return;
  // お問い合わせは常にオンラインで開き、学習画面のキャッシュに置き換えない。
  if (/\/(?:contact(?:-thanks)?|privacy|terms)(?:\.html)?\/?$/.test(url.pathname)||url.pathname.endsWith('/info.css')) return;

  // 画面遷移：キャッシュ優先＋裏で更新（オフラインでも必ず開ける）
  if (req.mode === 'navigate') {
    e.respondWith((async () => {
      const c = await caches.open(SHELL);
      const schedulePage = /\/schedule(?:\/|\/index\.html)?$/.test(url.pathname);
      const hit = schedulePage ? await c.match('./schedule/index.html') : await c.match('./index.html') || await c.match('./');
      return hit || (await fetch(req).catch(() => null)) || new Response('オフラインです', {
        status: 503, headers: { 'Content-Type': 'text/plain; charset=utf-8' } });
    })());
    return;
  }

  // 図表：キャッシュ優先。無ければ取得して保存（＝見たものだけ貯まる）
  if (isFig(url)) {
    e.respondWith((async () => {
      const c = await caches.open(FIGS);
      const hit = await c.match(req);
      if (hit) return hit;
      try {
        const r = await fetch(req);
        if (r.ok) c.put(req, r.clone());
        return r;
      } catch (err) {
        return new Response('', { status: 504 });
      }
    })());
    return;
  }

  // その他（js / css / json / icons）：キャッシュ優先＋裏で更新
  e.respondWith((async () => {
    const c = await caches.open(SHELL);
    const hit = await c.match(req);
    if (hit) return hit;
    try {
      const response = await fetch(req);
      if (response.ok) await c.put(req, response.clone());
      return response;
    } catch (err) { return new Response('', { status: 504 }); }

  })());
});

/* ---------- 画面からの指示 ---------- */
self.addEventListener('message', e => {
  const msg = e.data || {};

  if (msg.type === 'CACHE_TEXTBOOK_IMAGES') { e.waitUntil(cacheTextbookImages()); return; }

  if (msg.type === 'SKIP_WAITING') { self.skipWaiting(); return; }

  // 図表を一括先読み（設定画面の「図表をまとめてダウンロード」）
  if (msg.type === 'PRECACHE_FIGS') {
    e.waitUntil((async () => {
      const c = await caches.open(FIGS);
      const list = msg.urls || [];
      let done = 0, fail = 0;
      for (const u of list) {
        try {
          if (await c.match(u)) { done++; }
          else { const r = await fetch(u, { cache: 'reload' }); if (r.ok) { await c.put(u, r); done++; } else fail++; }
        } catch (err) { fail++; }
        if (done % 10 === 0 || done + fail === list.length) {
          const cl = await self.clients.matchAll();
          cl.forEach(x => x.postMessage({ type: 'FIGS_PROGRESS', done, fail, total: list.length }));
        }
      }
      const cl = await self.clients.matchAll();
      cl.forEach(x => x.postMessage({ type: 'FIGS_DONE', done, fail, total: list.length }));
    })());
    return;
  }

  // キャッシュ状況の問い合わせ
  if (msg.type === 'CACHE_STATUS') {
    e.waitUntil((async () => {
      const c = await caches.open(FIGS);
      const n = Array.isArray(msg.urls)
        ? (await Promise.all(msg.urls.map(u=>c.match(u)))).filter(Boolean).length
        : (await c.keys()).length;
      const cl = await self.clients.matchAll();
      cl.forEach(x => x.postMessage({ type: 'CACHE_STATUS', figs: n, ver: VER }));
    })());
  }
});
